{"command": "# I noticed a mistake: instrument numbers must be 1..128, not 0..127.
# I need to redo the setup with instruments 1, 2, 3, 4.

ft2 call module_new '{"channels": 4, "name": "Keygen Tune"}'

# Load samples into instruments 1-4
ft2 call sample_load '{"path": "sine_low.wav", "instrument": 1}'
ft2 call instrument_set '{"instrument": 1, "name": "Bass"}'

ft2 call sample_load '{"path": "sine_mid.wav", "instrument": 2}'
ft2 call instrument_set '{"instrument": 2, "name": "Lead"}'

ft2 call sample_load '{"path": "sine_hi.wav", "instrument": 3}'
ft2 call instrument_set '{"instrument": 3, "name": "Arp"}'

ft2 call sample_load '{"path": "noise.wav", "instrument": 4}'
ft2 call instrument_set '{"instrument": 4, "name": "Perc"}'

# Set song metadata
ft2 call song_set '{"bpm": 125, "length": 1, "loop_start": 0}'
ft2 call pattern_set_length '{"pattern": 0, "rows": 64}'
ft2 call order_set '{"position": 0, "pattern": 0}'

# Update generate_patterns.py to use instruments 1-4
cat << 'EOF' > generate_patterns.py
import json

calls = []

# Bass (Channel 0): instrument 1
bass_notes = [36, 36, 43, 36] * 16
for row, note in enumerate(bass_notes):
    calls.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 0, "row": row, "channel": 0, 
            "note": note, "instrument": 1, "volume": 64
        }
    })

# Percussion (Channel 1): instrument 4
for row in range(0, 64, 8):
    calls.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": 0, "row": row, "channel": 1, 
            "note": 48, "instrument": 4, "volume": 64
        }
